import {createCombat,EVENTS} from './engine.mjs';
const host=window.KFBAudioSite,box=document.createElement('section');box.className='panel';box.id='combat';
const names={punchLight:'Faust · leicht',punchHeavy:'Faust · schwer',knuckles:'Knöchel / Metall',whoosh:'Schwung',blaster:'Blaster',rocketLaunch:'Rakete · Start',fuse:'Zündschnur',explosionSmall:'Explosion · klein',explosionLarge:'Explosion · groß',hitConfirm:'Treffer bestätigt',fluffBurst:'Fluff platzt',treeShake:'Baum schütteln',botAngry:'Bot ärgerlich',botCollapse:'Bot zerfällt',woodBreak:'Holz bricht',stoneBreak:'Stein bricht',crystalBreak:'Kristall bricht',dominoChain:'Domino · Kette'};
box.innerHTML=`<style>#combat .cb-row{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:12px 0}#cb-board{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:7px}#cb-data{white-space:pre-wrap;max-height:350px;overflow:auto}</style><div class="eyebrow">AUDIO OWNER · PRIVATE DROPBOX-QUELLEN · R1</div><h2>KAMPF &amp; ZERSTÖRUNG</h2><p class="tiny">18 Ereignisse, je drei Varianten. Klick = ein Ereignis. Keine Spiel- oder Weltintegration vorweggenommen.</p><div class="cb-row"><button class="btn primary" id="cb-start">Bereit machen</button><button class="btn" id="cb-stop">Alles hier stoppen</button><button class="btn" id="cb-demo">30-s-Kampf-Demo</button><button class="btn" id="cb-ten">Auswahl 10× testen</button></div><div class="cb-row"><label>Auswahl <select id="cb-event">${Object.keys(EVENTS).map(k=>'<option value="'+k+'">'+names[k]+'</option>').join('')}</select></label><label>Entfernung <input id="cb-distance" type="range" min="1" max="60" value="3"><output id="cb-distance-out">3 m</output></label><label>Raum <select id="cb-room"><option value="outdoor">Draußen · trocken</option><option value="small-room">Kleiner Raum</option><option value="forest">Wald · kurze Reflexion</option></select></label><label>Material <select id="cb-material"><option value="stone">Stein</option><option value="wood">Holz</option><option value="crystal">Kristall</option></select></label></div><div id="cb-board">${Object.keys(EVENTS).map(k=>'<button class="btn" data-cb-event="'+k+'">'+names[k]+'</button>').join('')}</div><div class="cb-row"><button class="btn" id="cb-music">Musik: aus</button><button class="btn" id="cb-focus">Sprachfokus: aus</button><a id="cb-recording" hidden>Demo-Aufnahme herunterladen</a></div><output id="cb-status" aria-live="polite">Gestoppt · kein Autoplay.</output><details><summary>Messungen, Schichten &amp; offene Quellen</summary><p class="tiny">Standard: echte körperliche Ereignisse, Schwung + Körper und bei Explosionen Materialnachklang. Die unabhängigen Spezialschichten fehlen teilweise noch. Domino ist eine ganze Kette, kein einzelner Kontakt; Zündschnur wird nicht ungeprüft geloopt.</p><label><input id="cb-layers" type="checkbox"> Experiment: drei unabhängig gewählte Ausschnitte aus Kompositaufnahmen (nicht abgenommen)</label><p><a href="./combat/CONSUMER.md" target="_blank">Anschluss / bestehende Trigger</a> · <a href="./combat/manifest.json" target="_blank">Lizenzen / SHA</a> · <a href="./combat/WS0_GAPS.json" target="_blank">Wunschliste WS0</a></p><pre id="cb-data"></pre></details>`;
document.querySelector('#soundscape').prepend(box);const shortcut=document.createElement('button');shortcut.id='cb-shortcut';shortcut.textContent='Kampf';shortcut.onclick=()=>{document.querySelector('[data-view="soundscape"]').click();box.scrollIntoView({block:'start'});};document.querySelector('.tabs').append(shortcut);
const $=id=>box.querySelector('#'+id);let engine,pending,generation=0,music=false,musicGeneration=0,voice=false,paintAt=-1,recorder,capture,clipUrl;
async function ensure(){if(engine)return engine;if(pending)return pending;pending=(async()=>{const g=await host.resume();engine=await createCombat({audioContext:g.ctx,destination:g.buses.WORLD_SFX});return engine;})().finally(()=>pending=null);return pending;}
async function ready(){const g=++generation;$('cb-status').textContent='Private Quellen prüfen und laden …';try{const e=await ensure();if(g!==generation)return null;await e.start();if(g!==generation)return null;e.setContext({room:$('cb-room').value,experimentalLayers:$('cb-layers').checked});$('cb-status').textContent='Bereit · Hörabnahme offen.';paint();return e;}catch(err){if(g!==generation)return null;engine?.stop();$('cb-status').textContent='Nicht gestartet: '+err.message;return null;}}
function finish(){if(recorder?.state==='recording')recorder.stop();capture?.disconnect();capture=null;}
function record(){finish();if(!window.MediaRecorder)return;try{capture=engine.createCapture();const chunks=[],type=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(x=>MediaRecorder.isTypeSupported(x)),r=new MediaRecorder(capture.stream,type?{mimeType:type}:{});recorder=r;r.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};r.onstop=()=>{if(clipUrl)URL.revokeObjectURL(clipUrl);clipUrl=URL.createObjectURL(new Blob(chunks,{type:r.mimeType}));$('cb-recording').href=clipUrl;$('cb-recording').download='kfb-combat-r1-demo.'+(r.mimeType.includes('mp4')?'m4a':'webm');$('cb-recording').hidden=false;};r.start();}catch(err){$('cb-status').textContent='Demo läuft; Aufnahme nicht verfügbar: '+err.message;}}
function stop(){generation++;musicGeneration++;engine?.stop();finish();if(music)host.adaptiveMusic.stop();music=false;if(voice)host.musicContext.setVoiceActive(false,{source:'combat-stop'});voice=false;$('cb-music').textContent='Musik: aus';$('cb-focus').textContent='Sprachfokus: aus';$('cb-status').textContent='Gestoppt · alle Kampf-/Zerstörungsstimmen beendet.';paint();}
function paint(){if(!engine)return;const s=engine.snapshot(),t=host.audioContext.currentTime;if(s.demoUntil===null&&s.queued===0&&s.activeSources===0&&recorder?.state==='recording')finish();if(t-paintAt<.1&&s.active)return;paintAt=t;$('cb-data').textContent=JSON.stringify({revision:'0.9.0',hostContexts:host.audioContextsCreated,...s,log:s.log.slice(-50)},null,2);}
host.registerAudioTick(()=>{if(!engine)return;engine.setMix(host.getMixActivity());engine.tick();paint();});
$('cb-start').onclick=ready;$('cb-stop').onclick=stop;$('cb-demo').onclick=async()=>{const e=await ready();if(e){e.schedule('fight',undefined,{position:{x:0,y:0,z:-Number($('cb-distance').value)},material:$('cb-material').value});record();}};$('cb-ten').onclick=async()=>{const e=await ready();if(e){e.schedule('ten',$('cb-event').value,{position:{x:0,y:0,z:-Number($('cb-distance').value)},material:$('cb-material').value});record();}};
box.querySelectorAll('[data-cb-event]').forEach(b=>b.onclick=async()=>{const e=await ready();e?.emit({type:b.dataset.cbEvent,position:{x:0,y:0,z:-Number($('cb-distance').value)},material:$('cb-material').value});paint();});
$('cb-distance').oninput=()=>{$('cb-distance-out').textContent=$('cb-distance').value+' m';};$('cb-room').onchange=()=>engine?.setContext({room:$('cb-room').value});$('cb-layers').onchange=()=>engine?.setContext({experimentalLayers:$('cb-layers').checked});
$('cb-music').onclick=async()=>{const g=++musicGeneration;try{if(music){host.adaptiveMusic.stop();music=false;}else{await host.adaptiveMusic.startDeck('D');if(g!==musicGeneration){host.adaptiveMusic.stop();return;}music=true;}$('cb-music').textContent='Musik: '+(music?'an':'aus');}catch(err){$('cb-status').textContent=err.message;}};$('cb-focus').onclick=()=>{voice=!voice;host.musicContext.setVoiceActive(voice,{source:'combat-focus-test'});$('cb-focus').textContent='Sprachfokus: '+(voice?'an':'aus');};
host.combat={getSnapshot:()=>engine?.snapshot()||{active:false,combatActive:false},emit:cue=>engine?.emit(cue),stop};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});window.addEventListener('pagehide',stop);if(location.hash==='#combat')shortcut.click();
